#!/usr/bin/env python3
"""Restore manually matched tissue pages; input is the user's four PDF files."""
from pathlib import Path
import sys,json,io
import pymupdf as pdf
from PIL import Image
root=Path(__file__).resolve().parents[1]
folder=Path(sys.argv[1]) if len(sys.argv)>1 else Path('/tmp/arena-coding-uploads')
out=root/'assets/histology/tissues';out.mkdir(parents=True,exist_ok=True)
files=['nervnaya_tkan.pdf','mishichn_tkani.pdf','soedinitelnye_tkani_voloknistye_so_specialnymi_svoistvami_ehmbrionalnye.pdf','preparati_tkani_vnutr_sredi 2.pdf']
docs=[pdf.open(folder/f) for f in files]
def page(i,n):
 name=f'd{i+1}-{n:03}.webp';target=out/name
 if not target.exists():
  pix=docs[i][n-1].get_pixmap(matrix=pdf.Matrix(1.35,1.35),alpha=False)
  Image.open(io.BytesIO(pix.tobytes('png'))).convert('RGB').save(target,'WEBP',quality=84,method=6)
 return f'assets/histology/tissues/{name}'
def source(i,n):return f'{3 if i<2 else 2}-й коллоквиум · {files[i]}, стр. {n}'
def pair(i,n,stain=None,number=None):
 assert not docs[i][n-1].get_text().strip(),(i,n)
 v={'image':page(i,n),'review':page(i,n+1),'source':source(i,n+1),'note':'Сверьте поле зрения с исходной страницей с обозначениями.'}
 if stain:v['stain']=stain
 if number:v['number']=number
 return v
